#include <stdio.h>

int main(void)
{
    char a;
    short b;
    int c;
    long d;
    long long e;
    float f;
    double g;

    scanf("%c", &a);
    scanf("%hd", &b);
    scanf("%d", &c);
    scanf("%ld", &d);
    scanf("%lld", &e);
    scanf("%f", &f);
    scanf("%lf", &g);

    printf("The 'char' variable is %c, it takes %zu byte.\n", a, sizeof(a));
    printf("The 'short' variable is %hd, it takes %zu bytes.\n", b, sizeof(b));
    printf("The 'int' variable is %d, it takes %zu bytes.\n", c, sizeof(c));
    printf("The 'long' variable is %ld, it takes %zu bytes.\n", d, sizeof(d));
    printf("The 'long long' variable is %lld, it takes %zu bytes.\n", e, sizeof(e));
    printf("The 'float' variable is %f, it takes %zu bytes.\n", f, sizeof(f));
    printf("The 'double' variable is %f, it takes %zu bytes.\n", g, sizeof(g));
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void)
{
    int a, b, c;

    scanf("%d%d%d", &a, &b, &c);
    if (a + b > c && a + c > b && b + c > a) {
        double s = (a + b + c) / 2.0;
        double area = sqrt(s * (s - a) * (s - b) * (s - c));
        printf("%.3f\n", area);
    } else {
        printf("The edges cannot make up of a triangle.\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    double p1, p2, p3;
    char member;
    long long cents;

    scanf("%lf%lf%lf", &p1, &p2, &p3);
    scanf(" %c", &member);

    cents = (long long)(p1 * 100 + 0.5)
          + (long long)(p2 * 100 + 0.5)
          + (long long)(p3 * 100 + 0.5);

    if (cents >= 30000) {
        cents -= 5000;
    } else if (cents >= 20000) {
        cents -= 3000;
    } else if (cents >= 10000) {
        cents -= 1000;
    }

    if (member == 'Y') {
        cents = (cents * 95 + 50) / 100;
    }

    printf("%lld.%02lld\n", cents / 100, cents % 100);
    return 0;
}

#include <stdio.h>

