    scanf("%d%d", &a, &b);
    if (a == b) {
        printf("The two numbers are equal.\n");
    } else {
        if (a > b) {
            max = a;
            min = b;
        } else {
            max = b;
            min = a;
        }
        printf("The larger number is %d, the smaller number is %d.\n", max, min);
    }
    return 0;
}

