#include <stdio.h>

int main(void)
{
    int y, m, d, leap, sum;

    scanf("%d%d%d", &y, &m, &d);
    leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    sum = d;

    switch (m) {
    /* 11 月：30 天 */
    case 12: sum += 30;  /* fall through */
    /* 10 月：31 天 */
    case 11: sum += 31;  /* fall through */
    /* 9 月：30 天 */
    case 10: sum += 30;  /* fall through */
    /* 8 月：31 天 */
    case 9:  sum += 31;  /* fall through */
    /* 7 月：31 天 */
    case 8:  sum += 31;  /* fall through */
    /* 6 月：30 天 */
    case 7:  sum += 30;  /* fall through */
    /* 5 月：31 天 */
    case 6:  sum += 31;  /* fall through */
    /* 4 月：30 天 */
    case 5:  sum += 30;  /* fall through */
    /* 3 月：31 天 */
    case 4:  sum += 31;  /* fall through */
    /* 2 月：闰年 29 天，平年 28 天 */
    case 3:  sum += leap ? 29 : 28;  /* fall through */
    /* 1 月：31 天 */
    case 2:  sum += 31;  /* fall through */
    case 1:  break;
    default: break;
    }

    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x;

    scanf("%d", &x);
    if (x < 1 || x > 10000) {
        printf("%d out of range\n", x);
    } else {
        long long sq = (long long)x * x;
        long long p = 10;
        while (p <= x) {
            p *= 10;
        }
        if (sq % p == x) {
            printf("Yes\n");
        } else {
            printf("No\n");
        }
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int m, n, rest, k, d, r, c;

    scanf("%d%d", &m, &n);
    rest = n - 2 * m;              /* 2r + 4d = n - 2m */
    if (rest >= 0 && rest % 2 == 0) {
        k = rest / 2;              /* r + 2d = k */
        for (d = 0; d <= k / 2; d++) {
            r = k - 2 * d;
            c = m - r - d;
            if (c >= 0 && r >= 0) {
                printf("%d %d %d\n", c, r, d);
            }
        }
    }
    return 0;
}

