#include <stdio.h>

int main(void)
{
    double s, fee;
    char period;

    scanf("%lf", &s);
    scanf(" %c", &period);

    if (s <= 3.0) {
        fee = 13.0;
    } else if (s <= 15.0) {
        fee = 13.0 + (s - 3.0) * 2.30;
    } else {
        fee = 13.0 + 12.0 * 2.30 + (s - 15.0) * 3.45;
    }
    if (period == 'N') {
        fee = fee * 1.2;
    }
    printf("%.2f\n", fee);
    return 0;
}
